class Solution:
    def calculateScore(self, s: str) -> int:
        n = len(s)
        marked = [False] * n
        ans = 0
        for i in range(n):
            m = chr(ord('z') - (ord(s[i]) - ord('a')))
            for j in range(i - 1, -1, -1):
                if not marked[j] and s[j] == m:
                    marked[i] = marked[j] = True
                    ans += i - j
                    break
        return ans

