class Solution {
public:
    long long calculateScore(string s) {
        int n = s.size();
        vector<bool> marked(n, false);
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            char m = 'z' - (s[i] - 'a');
            for (int j = i - 1; j >= 0; j--) {
                if (!marked[j] && s[j] == m) {
                    marked[i] = marked[j] = true;
                    ans += i - j;
                    break;
                }
            }
        }
        return ans;
    }
};

