class Solution:
    def calculateScore(self, s: str) -> int:
        st = [[] for _ in range(26)]
        ans = 0
        for i, ch in enumerate(s):
            x = ord(ch) - 97
            m = 25 - x
            if st[m]:
                ans += i - st[m].pop()
            else:
                st[x].append(i)
        return ans

