class Solution {
public:
    long long calculateScore(string s) {
        vector<vector<int>> st(26);
        long long ans = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            int x = s[i] - 'a', m = 25 - x;
            if (!st[m].empty()) {
                ans += i - st[m].back();
                st[m].pop_back();
            } else {
                st[x].push_back(i);
            }
        }
        return ans;
    }
};

