class Solution {
    public long calculateScore(String s) {
        List<List<Integer>> st = new ArrayList<>();
        for (int i = 0; i < 26; i++) st.add(new ArrayList<>());
        long ans = 0;
        for (int i = 0; i < s.length(); i++) {
            int x = s.charAt(i) - 'a', m = 25 - x;
            List<Integer> stk = st.get(m);
            if (!stk.isEmpty()) {
                ans += i - stk.remove(stk.size() - 1);
            } else {
                st.get(x).add(i);
            }
        }
        return ans;
    }
}

